#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <sstream>

int main() {
    std::string filename;
    std::string word_to_count;

    std::cout << "Enter the filename: ";
    std::cin >> filename;

    std::cout << "Enter the word to count: ";
    std::cin >> word_to_count;

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    std::vector<int> word_counts(1000, 0); // Assuming a maximum of 1000 unique words. Adjust as needed.
    std::string line;

    while (std::getline(file, line)) {
        std::stringstream ss(line);
        std::string word;
        while (ss >> word) {
            if (word == word_to_count) {
                word_counts[word.length() % 1000]++; // Use modulo to handle potential out-of-bounds access
            }
        }
    }

    file.close();

    int total_count = 0;
    for (int count : word_counts) {
        total_count += count;
    }

    std::cout << "The word '" << word_to_count << "' appears " << total_count << " times in the file." << std::endl;

    return 0;
}
